import Image from "next/image";

// INTERIM asset generated by scripts/build-wordmark.mjs from the supplied JPG (spectrum variant).
// When JellyLabs-wordmark.svg arrives, drop it in /public/brand and update src + intrinsic size here.
const WORDMARK = { src: "/brand/jellylabs-wordmark.webp", width: 640, height: 151 } as const;

export function Wordmark({ className = "h-7 w-auto", priority = false }: { className?: string; priority?: boolean }) {
  return (
    <Image
      src={WORDMARK.src}
      width={WORDMARK.width}
      height={WORDMARK.height}
      alt="Jelly Labs"
      priority={priority}
      unoptimized // already optimised at build; keeps the alpha edge exact
      className={className}
    />
  );
}
